--
-- Estructura de tabla para la tabla `cortes_linea`
--

CREATE TABLE `cortes_linea` (
  `id` int(11) UNSIGNED NOT NULL,
  `id_dispositivo` int(11) UNSIGNED NOT NULL,
  `id_usuario` int(11) UNSIGNED NOT NULL,
  `consumo_actual` decimal(10,4) NOT NULL COMMENT 'Consumo en kWh cuando se cortó la línea',
  `limite_configurado` decimal(10,4) NOT NULL COMMENT 'Límite configurado en kWh',
  `fecha_corte` datetime NOT NULL COMMENT 'Fecha y hora del corte',
  `vista_por_usuario` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=No vista, 1=Vista por el usuario',
  `fecha_vista` datetime DEFAULT NULL COMMENT 'Fecha y hora cuando el usuario vio la alerta',
  `resuelto` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=Corte activo, 1=Resuelto',
  `fecha_resolucion` datetime DEFAULT NULL COMMENT 'Fecha y hora cuando se resolvió el corte',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `tipo` enum('prealerta','corte') NOT NULL DEFAULT 'corte'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabla para registrar cortes de línea no esencial';

