--
-- Índices para tablas volcadas
--

--
-- Indices de la tabla `compra`
--
ALTER TABLE `compra`
  ADD PRIMARY KEY (`id_compra`),
  ADD KEY `id_usuario` (`id_usuario`);

--
-- Indices de la tabla `cortes_linea`
--
ALTER TABLE `cortes_linea`
  ADD PRIMARY KEY (`id`),
  ADD KEY `idx_id_dispositivo` (`id_dispositivo`),
  ADD KEY `idx_id_usuario` (`id_usuario`),
  ADD KEY `idx_vista_por_usuario` (`vista_por_usuario`),
  ADD KEY `idx_resuelto` (`resuelto`),
  ADD KEY `idx_fecha_corte` (`fecha_corte`);

--
-- Indices de la tabla `direcciones`
--
ALTER TABLE `direcciones`
  ADD PRIMARY KEY (`direccion_id`);

--
-- Indices de la tabla `dispositivos`
--
ALTER TABLE `dispositivos`
  ADD PRIMARY KEY (`id_dispositivo`),
  ADD UNIQUE KEY `mac_address` (`mac_address`),
  ADD KEY `id_usuario` (`id_usuario`);

--
-- Indices de la tabla `energia`
--
ALTER TABLE `energia`
  ADD PRIMARY KEY (`id`),
  ADD KEY `idx_energia_dispositivo_fecha` (`id_dispositivo`,`fecha`);

--
-- Indices de la tabla `energia_resumen_diario`
--
ALTER TABLE `energia_resumen_diario`
  ADD PRIMARY KEY (`id`),
  ADD UNIQUE KEY `uq_dispositivo_fecha` (`id_dispositivo`,`fecha`),
  ADD KEY `idx_dispositivo_fecha` (`id_dispositivo`,`fecha`);

--
-- Indices de la tabla `invitaciones`
--
ALTER TABLE `invitaciones`
  ADD PRIMARY KEY (`id_invitacion`),
  ADD UNIQUE KEY `token` (`token`),
  ADD KEY `id_rol` (`id_rol`);

--
